// Compiles schema/course-content.schema.json into plain JavaScript (Ajv standalone code), so the
// app validates content without `new Function`, which the production Content-Security-Policy
// forbids. Run after changing the schema: `pnpm gen:validator`. tests/content.test.ts fails if
// the generated file is out of date.
import { readFileSync, writeFileSync } from 'node:fs';
import Ajv2020 from 'ajv/dist/2020';
import standaloneCode from 'ajv/dist/standalone';

// Same as ajv/dist/runtime/ucs2length: string length in Unicode code points.
const UCS2LENGTH = `function ucs2length(str) { let length = 0, pos = 0, value; while (pos < str.length) { length++; value = str.charCodeAt(pos++); if (value >= 0xd800 && value <= 0xdbff && pos < str.length) { value = str.charCodeAt(pos); if ((value & 0xfc00) === 0xdc00) pos++; } } return length; }`;

export const GENERATED = 'src/content/schema-validator.generated.js';

export function generate(): string {
  const schema = JSON.parse(readFileSync('schema/course-content.schema.json', 'utf8'));
  const ajv = new Ajv2020({ allErrors: true, strict: false, code: { source: true, esm: true } });
  // Ajv still emits a CommonJS require for its string-length helper; inline it so the module is
  // plain ESM in the browser and in Node.
  const code = standaloneCode(ajv, ajv.compile(schema)).replace('require("ajv/dist/runtime/ucs2length").default', UCS2LENGTH);
  if (/\brequire\(/.test(code)) throw new Error('generated validator still contains require(); inline the helper');
  return `// @ts-nocheck\n// GENERATED by scripts/build-validator.ts from schema/course-content.schema.json. Do not edit.\n${code}\n`;
}

if (process.argv[1]?.endsWith('build-validator.ts')) {
  writeFileSync(GENERATED, generate());
  console.log(`wrote ${GENERATED}`);
}
